import requests
import json

url = "https://open.admin.shopee.io/api/v2/merchant/list_shop_by_warehouse?access_token=access_token&merchant_id=merchant_id&partner_id=partner_id&sign=sign&timestamp=timestamp"

payload=json.dumps({
  "cursor": {},
  "warehouse_id": 100,
  "warehouse_type": 1
})
headers = {
  'Content-Type': 'application/json'
}
response = requests.RPCRequest("POST",url,headers=headers, data=payload, allow_redirects=False)

print(response.text)

